package dev.starfold;

/** Bounded development clicks through handleKeybinds, plus hostile packet attempts. No production activation. */
public final class DevFeelProbe {
    private static net.minecraft.core.BlockPos target;private static net.minecraft.world.level.block.state.BlockState before;private static String action;private static int left,swings,changes;private static boolean first;
    static void start(net.minecraft.client.Minecraft mc,String args){var a=args.split("\\s+");action=a[1];left=Integer.parseInt(a[2]);swings=changes=0;first=true;target=null;var body=dev.ryanhcode.sable.Sable.HELPER.getTrackingSubLevel(mc.player);var bounds=body.getPlot().getBoundingBox();var eye=body.logicalPose().transformPositionInverse(new org.joml.Vector3d(mc.player.getX(),mc.player.getEyeY(),mc.player.getZ()));double nearest=Double.POSITIVE_INFINITY;for(var p:net.minecraft.core.BlockPos.betweenClosed(bounds.minX(),bounds.minY(),bounds.minZ(),bounds.maxX(),bounds.maxY(),bounds.maxZ())){var s=mc.level.getBlockState(p);double distance=eye.distanceSquared(p.getX()+.5,p.getY()+.5,p.getZ()+.5);boolean matches=a[0].equals("nose")?s.getBlock() instanceof NativeThruster.ScopeBlock&&s.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.FACING)==NativeHelmInputClient.facing((dev.ryanhcode.sable.sublevel.ClientSubLevel)body):s.getBlock().toString().contains(a[0]);if(matches&&distance<nearest){nearest=distance;target=p.immutable();before=s;}}if(target==null)throw new IllegalStateException("No test block "+a[0]);org.slf4j.LoggerFactory.getLogger("starfold-probe").info("PROBE FEEL_BEGIN {} action {} ticks {} target {} state {} pilot {}",a[0],action,left,target,before,NativeHelmClient.body()!=null);}
    private static net.minecraft.world.phys.BlockHitResult hit(){return new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(target),net.minecraft.core.Direction.UP,target,false);}
    public static void prepare(net.minecraft.client.Minecraft mc){if(!DevProbe.active()||left<=0)return;mc.hitResult=hit();mc.mouseHandler.grabMouse();var key=action.equals("attack")?mc.options.keyAttack:mc.options.keyUse;key.setDown(true);if(first){net.minecraft.client.KeyMapping.click(key.getKey());first=false;}}
    static boolean tick(net.minecraft.client.Minecraft mc){if(left<=0)return false;
        if(action.equals("packet")){mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundPlayerActionPacket(net.minecraft.network.protocol.game.ServerboundPlayerActionPacket.Action.START_DESTROY_BLOCK,target,net.minecraft.core.Direction.UP,0));mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundPlayerActionPacket(net.minecraft.network.protocol.game.ServerboundPlayerActionPacket.Action.STOP_DESTROY_BLOCK,target,net.minecraft.core.Direction.UP,0));mc.player.connection.send(new net.minecraft.network.protocol.game.ServerboundUseItemOnPacket(net.minecraft.world.InteractionHand.MAIN_HAND,hit(),0));}
        if(mc.player.swinging)swings++;if(mc.level.getBlockState(target)!=before)changes++;if(--left==0){mc.options.keyAttack.setDown(false);mc.options.keyUse.setDown(false);org.slf4j.LoggerFactory.getLogger("starfold-probe").info("PROBE FEEL_END action {} target {} swingTicks {} changedTicks {} final {}",action,target,swings,changes,mc.level.getBlockState(target));String at=target.toShortString().replace(",","");mc.player.connection.sendCommand("execute if block "+at+" "+net.minecraft.core.registries.BuiltInRegistries.BLOCK.getKey(before.getBlock())+" run tellraw @s \"FEEL_SERVER_INTACT "+action+" "+at+"\"");mc.player.connection.sendCommand("execute if block "+at+" minecraft:air run tellraw @s \"FEEL_SERVER_BROKEN "+at+"\"");}return true;}
    private DevFeelProbe(){}
}
